    price6Name:   { en: "Platform or marketplace",     pl: "Platforma lub marketplace", ru: "Платформа или маркетплейс", tr: "Platform veya pazar yeri", es: "Plataforma o marketplace" },
    price6Amount: { en: "from €3000",                  pl: "od 3000 €",                 ru: "от 3000 €", tr: "3000 €'dan", es: "desde 3000 €" },
    price6Time:   { en: "from 6 weeks",                pl: "od 6 tygodni",              ru: "от 6 недель", tr: "6 haftadan", es: "desde 6 semanas" },
    price4Name:   { en: "Ongoing SEO / ASO / AI",      pl: "Stałe SEO / ASO / AI",       ru: "Постоянное SEO / ASO / AI", tr: "Sürekli SEO / ASO / AI", es: "SEO / ASO / AI continuo" },
    price4Desc:   { en: "What keeps you found after launch — Google profile, reviews, search, AI answers. Monthly, stop whenever you want.", pl: "To, dzięki czemu znajdują Cię po starcie — profil Google, opinie, wyszukiwarka, odpowiedzi AI. Miesięcznie, rezygnujesz kiedy chcesz.", ru: "То, благодаря чему тебя находят после запуска — профиль Google, отзывы, поиск, ответы AI. Ежемесячно, отказаться можно в любой момент.", tr: "Yayına girdikten sonra bulunmanı sağlayan şey — Google profili, yorumlar, arama, yapay zekâ yanıtları. Aylık, istediğin zaman bırakırsın.", es: "Lo que hace que te sigan encontrando tras el lanzamiento — perfil de Google, reseñas, búsqueda, respuestas de IA. Mensual, lo dejas cuando quieras." },
    price4Amount: { en: "from €200/mo",                pl: "od 200 €/mies.",             ru: "от 200 €/мес", tr: "200 €/ay'dan", es: "desde 200 €/mes" },
